import { execFileSync } from "node:child_process";

type FileDiff = { path: string; deleted: boolean; added: string[]; removed: string[] };

const TEST_FILE = /(^|\/)(tests?|e2e)\/|\.(test|spec)\.tsx?$|(^|\/)test_[^/]*\.py$/;
const SKIP = /\b(it|test|describe)\.(skip|only|fixme)\(|@pytest\.mark\.(skip|xfail)/;
const ASSERT = /\bassert\b|\bexpect\(/;
const THRESHOLD = /(fail[-_]under|retries|timeout\w*)\s*[:=]\s*([\d.]+)/i;

// read `git diff` output into one entry per file
const parseDiff = (text: string): FileDiff[] => {
  const files: FileDiff[] = [];
  let f: FileDiff | undefined;
  for (const line of text.split("\n")) {
    const head = /^diff --git a\/(\S+) b\//.exec(line);
    if (head) files.push((f = { path: head[1], deleted: false, added: [], removed: [] }));
    else if (!f || line.startsWith("+++") || line.startsWith("---")) continue;
    else if (line.startsWith("deleted file")) f.deleted = true;
    else if (line.startsWith("+")) f.added.push(line.slice(1));
    else if (line.startsWith("-")) f.removed.push(line.slice(1));
  }
  return files;
};

const count = (rx: RegExp, lines: string[]) => lines.filter((l) => rx.test(l)).length;

const thresholds = (lines: string[]) =>
  new Map(lines.map((l) => THRESHOLD.exec(l)).filter((m) => m !== null).map((m) => [m[1], Number(m[2])]));

export const falseHeals = (diff: FileDiff[], never: Set<string>): string[] => {
  const found: string[] = [];
  for (const f of diff) {
    const isTest = TEST_FILE.test(f.path);
    if (f.deleted && isTest) found.push(`${f.path}: test file deleted`);
    for (const line of f.added.filter((l) => SKIP.test(l))) found.push(`${f.path}: new skip \`${line.trim()}\``);
    if (isTest) {
      const removed = count(ASSERT, f.removed), added = count(ASSERT, f.added);
      if (removed > added) found.push(`${f.path}: ${removed - added} assertion(s) removed`);
      if (never.has("edit_test_assertions") && removed > 0) found.push(`${f.path}: an existing assertion was changed`);
    }
    const before = thresholds(f.removed), after = thresholds(f.added);
    for (const [key, oldValue] of before) {
      const newValue = after.get(key);
      if (newValue === undefined) continue;
      const loosened = key.toLowerCase().includes("fail") ? newValue < oldValue : newValue > oldValue;
      if (loosened) found.push(`${f.path}: ${key} loosened ${oldValue} -> ${newValue}`);
    }
  }
  return found;
};

const [repo, branch] = process.argv.slice(2);
const diff = execFileSync("git", ["-C", repo, "diff", `main...${branch}`], { encoding: "utf8" });
const found = falseHeals(parseDiff(diff), new Set(["edit_test_assertions"]));
console.log(found.length ? `✘ ${branch}: false heal\n  ${found.join("\n  ")}` : `✔ ${branch}: no false heal`);
process.exitCode = found.length ? 1 : 0;
